// Run inside an ARIS report, not in a browser or Node.js.
var netUtils = Utilities.getNetUtils();
var headers = new java.util.HashMap();
headers.put("Accept", "application/json");

var responseText = netUtils.doRestCall(
    "https://jsonplaceholder.typicode.com/posts/1",
    "GET",
    "json",
    headers,
    null,   // No request body for this GET.
    10000,  // Connection timeout: 10 seconds.
    30000   // Read timeout: 30 seconds.
);

var post = JSON.parse(String(responseText));
if (!post || typeof post.id !== "number"
        || typeof post.title !== "string") {
    throw new Error("Unexpected API response: id and title required.");
}

var result = { id: post.id, title: post.title };

