// Alternative example: send a JSON payload.
var netUtils = Utilities.getNetUtils();
var headers = new java.util.HashMap();
headers.put("Content-Type", "application/json; charset=UTF-8");

var payload = JSON.stringify({
    title: "ARIS integration example",
    body: "Sent from an ARIS report",
    userId: 1
});

var responseText = netUtils.doRestCall(
    "https://jsonplaceholder.typicode.com/posts",
    "POST", "json", headers, payload, 10000, 30000
);

var created = JSON.parse(String(responseText));
if (!created || typeof created.id !== "number") {
    throw new Error("Unexpected API response: id required.");
}
